import { TextInput } from '@absoluteui/components/text-input';

const host = document.createElement('div');
document.body.append(host);
const email = TextInput.create(host, { label: 'Email', type: 'email', name: 'email', required: true, autocomplete: 'email' });
host.addEventListener('aui-change', () => {
  host.dataset.valid = String(email.validity.valid);
});

import { TextInput } from '@absoluteui/components/text-input';

const host = document.createElement('div');
document.body.append(host);
TextInput.create(host, {
  label: 'Username',
  maxLength: 20,
  showCounter: true,
  validate: (value) => (value.includes(' ') ? 'Usernames cannot contain spaces.' : null),
});

